def strtol_base0(s):
    i=0
    while i < len(s) and s[i] in ' \t\n\r\f\v':
        i+=1
    if i>=len(s):
        return (0,i,False)
    if s[i] in '+-':
        return (0,i,False)
    if s[i]=='0' and i+1 < len(s) and s[i+1] in 'xX':
        j=i+2
        start=j
        while j < len(s) and s[j] in '0123456789abcdefABCDEF':
            j+=1
        if j==start:
            return (0,i+1,True)
        else:
            try:
                val=int(s[i:j],16)
            except:
                val=0
            return (val,j,True)
    if s[i]=='0':
        j=i
        while j < len(s) and s[j] in '01234567':
            j+=1
        octal_str=s[i:j]
        if octal_str=="":
            octal_str="0"
        try:
            val=int(octal_str,8)
        except:
            val=0
        return (val,j,True)
    j=i
    while j < len(s) and s[j].isdigit():
        j+=1
    if j==i:
        return (0,i,False)
    try:
        val=int(s[i:j],10)
    except:
        val=0
    return (val,j,True)

def format_flag(value):
    hex_str=f"0x{value:x}"
    dec_str=f"{value}"
    names=[]
    for bit_val,dec,name,_ in FLAG_DEFS:
        if value & bit_val:
            names.append(name)
    if names:
        return f"{hex_str}\t{dec_str}\t{','.join(names)}\n"
    else:
        return f"{hex_str}\t{dec_str}\t\n"

def cmd_flags(argv):
    if not argv:
        sys.stdout.write(FLAGS_HELP)
        return 0
    exit_code=0
    for arg in argv:
        if arg=="":
            sys.stdout.write(format_flag(0))
            continue
        val,end_idx,consumed=strtol_base0(arg)
        if consumed:
            sys.stdout.write(format_flag(val))
            continue
        tokens=arg.split(',')
        sum_val=0
        ok=True
        for tok in tokens:
            if tok=="":
                ok=False
                break
            if tok!=tok.strip():
                ok=False
                break
            lower=tok.lower()
            if lower in FLAG_MAP:
                sum_val|=FLAG_MAP[lower]
            elif tok in FLAG_MAP:
                sum_val|=FLAG_MAP[tok]
            else:
                ok=False
                break
        if ok:
            sys.stdout.write(format_flag(sum_val))
        else:
            sys.stderr.write(f'samtools flags: Could not parse "{arg}"\n')
            sys.stderr.write(FLAGS_HELP)
            exit_code=1
    return exit_code

def parse_fasta(path):
    seqs=[]
    open_func=open
    mode='r'
    if path.endswith('.gz'):
        open_func=gzip.open
        mode='rt'
    try:
        with open_func(path,mode) as f:
            cur_name=None
            cur_seq=[]
            for line in f:
                line=line.rstrip('\n')
                if not line:
                    continue
                if line.startswith('>'):
                    if cur_name is not None:
                        seqs.append((cur_name,''.join(cur_seq)))
                    header=line[1:].strip()
                    name=header.split()[0] if header else ""
                    cur_name=name
                    cur_seq=[]
                else:
                    cur_seq.append(line.strip())
            if cur_name is not None:
                seqs.append((cur_name,''.join(cur_seq)))
    except FileNotFoundError:
        return None
    return seqs

def md5_upper(seq):
    return hashlib.md5(seq.upper().encode()).hexdigest()

def cmd_dict(argv):
    import getopt
    if not argv:
        sys.stdout.write("@HD\tVN:1.0\tSO:unsorted\n")
        return 0
    try:
        opts,args=getopt.getopt(argv,"a:AHl:o:s:u:h",["assembly=","alias","alternative-name","no-header","alt=","output=","species=","uri=","help"])
    except getopt.GetoptError as e:
        sys.stderr.write(f"dict: {e}\n\n")
        sys.stdout.write(DICT_HELP+"\n")
        return 1
    assembly=None
    alias=False
    no_header=False
    alt_file=None
    output_file=None
    species=None
    uri=None
    for o,a in opts:
        if o in ("-a","--assembly"):
            assembly=a
        elif o in ("-A","--alias","--alternative-name"):
            alias=True
        elif o in ("-H","--no-header"):
            no_header=True
        elif o in ("-l","--alt"):
            alt_file=a
        elif o in ("-o","--output"):
            output_file=a
        elif o in ("-s","--species"):
            species=a
        elif o in ("-u","--uri"):
            uri=a
        elif o in ("-h","--help"):
            sys.stdout.write(DICT_HELP+"\n")
            return 0
    if len(args)==0:
        if no_header:
            return 0
        else:
            sys.stdout.write("@HD\tVN:1.0\tSO:unsorted\n")
            return 0
    fasta_path=args[0]
    if not os.path.exists(fasta_path):
        sys.stderr.write(f"samtools dict: Cannot open {fasta_path}: No such file or directory\n")
        return 1
    seqs=parse_fasta(fasta_path)
    if seqs is None:
        sys.stderr.write(f"samtools dict: Cannot open {fasta_path}: No such file or directory\n")
        return 1
    out_f=sys.stdout
    if output_file:
        out_f=open(output_file,'w')
    if uri is None:
        abs_path=os.path.abspath(fasta_path)
        uri=f"file://{abs_path}"
    if not no_header:
        out_f.write("@HD\tVN:1.0\tSO:unsorted\n")
    for name,seq in seqs:
        ln=len(seq)
        m5=md5_upper(seq)
        line=f"@SQ\tSN:{name}\tLN:{ln}\tM5:{m5}\tUR:{uri}"
        if alias:
            an=name[3:] if name.startswith("chr") else "chr"+name
            line+=f"\tAN:{an}"
        if assembly is not None:
            line+=f"\tAS:{assembly}"
        if species is not None:
            line+=f"\tSP:{species}"
        line+="\n"
        out_f.write(line)
    if output_file:
        out_f.close()
    return 0

def revcomp(seq):
    comp={'A':'T','a':'t','T':'A','t':'a','C':'G','c':'g','G':'C','g':'c','N':'N','n':'n'}
    return ''.join(comp.get(b,b) for b in reversed(seq))

def parse_region(reg):
    if ':' not in reg:
        return (reg,None,None)
    name,coords=reg.split(':',1)
    coords_nocomma=coords.replace(',','')
    if '-' in coords_nocomma:
        s,e=coords_nocomma.split('-',1)
        try:
            start=int(s) if s!='' else None
        except:
            start=None
        try:
            end=int(e) if e!='' else None
        except:
            end=None
        return (name,start,end)
    else:
        try:
            start=int(coords_nocomma)
            return (name,start,start)
        except:
            return (name,None,None)

def faidx_index_file(fasta_path,fai_path=None):
    if fai_path is None:
        fai_path=fasta_path+".fai"
    seq_index={}
    try:
        f=open(fasta_path,'rb')
    except FileNotFoundError:
        return None
    cur_name=None
    cur_len=0
    cur_offset=None
    cur_line_bases=None
    cur_line_bytes=None
    first=True
    while True:
        pos=f.tell()
        line=f.readline()
        if not line:
            break
        if line.startswith(b'>'):
            if cur_name is not None:
                seq_index[cur_name]=(cur_len,cur_offset,cur_line_bases,cur_line_bytes)
            try:
                header=line[1:].decode().strip()
            except:
                header=line[1:].decode('utf-8',errors='ignore').strip()
            name=header.split()[0] if header else ""
            cur_name=name
            cur_len=0
            cur_offset=f.tell()
            cur_line_bases=None
            cur_line_bytes=None
            first=True
        else:
            stripped=line.rstrip(b'\r\n')
            l=len(stripped)
            cur_len+=l
            if first:
                cur_line_bases=l
                cur_line_bytes=len(line)
                first=False
    if cur_name is not None:
        seq_index[cur_name]=(cur_len,cur_offset,cur_line_bases,cur_line_bytes)
    f.close()
    with open(fai_path,'w') as out:
        for name,(length,off,lb,lby) in seq_index.items():
            out.write(f"{name}\t{length}\t{off}\t{lb}\t{lby}\n")
    return seq_index

def load_fai(fasta_path,fai_idx_path=None):
    if fai_idx_path is None:
        fai_idx_path=fasta_path+".fai"
    if not os.path.exists(fai_idx_path):
        idx=faidx_index_file(fasta_path,fai_idx_path)
        return idx
    index={}
    try:
        with open(fai_idx_path,'r') as f:
            for line in f:
                if not line.strip():
                    continue
                parts=line.strip().split('\t')
                if len(parts)<5:
                    continue
                name=parts[0]
                length=int(parts[1])
                offset=int(parts[2])
                line_bases=int(parts[3])
                line_bytes=int(parts[4])
                index[name]=(length,offset,line_bases,line_bytes)
    except FileNotFoundError:
        return None
    return index

def fetch_sequence(fasta_path,fai_index,seq_name,start=None,end=None):
    if seq_name not in fai_index:
        return None
    length,offset,line_bases,line_bytes=fai_index[seq_name]
    if start is None and end is None:
        s=1
        e=length
    elif start is not None and end is None:
        s=start
        e=start
    elif start is None and end is not None:
        s=1
        e=end
    else:
        s=start
        e=end
    if s is None:
        s=1
    if e is None:
        e=length
    if s<1:
        return ("","zero",s,e,length)
    if s>length:
        return ("","truncated",s,e,length)
    if e>length:
        truncated=True
        e=length
    else:
        truncated=False
    if s>e:
        return ("","zero",s,e,length)
    seq_parts=[]
    try:
        f=open(fasta_path,'rb')
    except:
        return None
    pos=s
    while pos<=e:
        line_num=(pos-1)//line_bases
        col=(pos-1)%line_bases
        file_off=offset+line_num*line_bytes+col
        remaining=line_bases-col
        to_read=min(remaining,e-pos+1)
        f.seek(file_off)
        data=f.read(to_read)
        try:
            seq=data.decode()
        except:
            seq=data.decode('utf-8',errors='ignore')
        seq=seq.replace('\n','').replace('\r','')
        seq_parts.append(seq)
        pos+=to_read
    f.close()
    seq_str=''.join(seq_parts)
    if truncated:
        return (seq_str,"truncated",s,e,length)
    else:
        return (seq_str,"ok",s,e,length)

def cmd_faidx(argv):
    import getopt
    if not argv:
        sys.stdout.write(FAIDX_HELP)
        return 1
    if '-h' in argv or '--help' in argv:
        sys.stdout.write(FAIDX_HELP)
        return 0
    try:
        opts,args=getopt.getopt(argv,"o:n:cr:ihf",["output=","length=","continue","region-file=","reverse-complement","mark-strand=","fai-idx=","gzi-idx=","fastq","help","output-fmt-option=","threads=","write-index"])
    except getopt.GetoptError as e:
        sys.stderr.write(f"faidx: {e}\n")
        sys.stdout.write(FAIDX_HELP)
        return 1
    output_file=None
    line_length=60
    continue_on_error=False
    region_file=None
    revcomp_flag=False
    mark_strand="rc"
    fai_idx_path=None
    for o,a in opts:
        if o in ("-o","--output"):
            output_file=a
        elif o in ("-n","--length"):
            try:
                line_length=int(a)
            except:
                line_length=60
        elif o in ("-c","--continue"):
            continue_on_error=True
        elif o in ("-r","--region-file"):
            region_file=a
        elif o in ("-i","--reverse-complement"):
            revcomp_flag=True
        elif o in ("--mark-strand",):
            mark_strand=a
        elif o in ("--fai-idx",):
            fai_idx_path=a
        elif o in ("-h","--help"):
            sys.stdout.write(FAIDX_HELP)
            return 0
    if not args:
        sys.stdout.write(FAIDX_HELP)
        return 1
    fasta_path=args[0]
    regions=args[1:]
    if region_file:
        try:
            with open(region_file,'r') as rf:
                for line in rf:
                    line=line.strip()
                    if not line:
                        continue
                    regions.append(line)
        except FileNotFoundError:
            sys.stderr.write(f"[faidx] Failed to read region file {region_file}\n")
            return 1
    if not os.path.exists(fasta_path):
        sys.stderr.write(f"[faidx] Failed to open FASTA file {fasta_path}\n")
        return 1
    if fai_idx_path is None:
        fai_idx_path=fasta_path+".fai"
    fai_index=load_fai(fasta_path,fai_idx_path)
    if fai_index is None:
        fai_index=faidx_index_file(fasta_path,fai_idx_path)
        if fai_index is None:
            sys.stderr.write(f"[faidx] Failed to open FASTA file {fasta_path}\n")
            return 1
    if not regions:
        return 0
    out_f=sys.stdout
    if output_file:
        out_f=open(output_file,'w')
    def get_suffix(is_rc,mt):
        if not is_rc:
            if mt=="rc" or mt=="no":
                return ""
            elif mt=="sign":
                return "(+)"
            elif mt.startswith("custom,"):
                parts=mt.split(',',2)
                return parts[1] if len(parts)==3 else ""
            else:
                return ""
        else:
            if mt=="rc":
                return "/rc"
            elif mt=="no":
                return ""
            elif mt=="sign":
                return "(-)"
            elif mt.startswith("custom,"):
                parts=mt.split(',',2)
                return parts[2] if len(parts)==3 else ""
            else:
                return "/rc"
    exit_code=0
    for reg in regions:
        seq_name,start,end=parse_region(reg)
        if seq_name not in fai_index:
            sys.stderr.write(f"[W::fai_get_val] Reference {reg} not found in FASTA file, returning empty sequence\n")
            sys.stderr.write(f"[W::fai_get_val] Reference {reg} not found in FASTA file, returning empty sequence\n")
            sys.stderr.write(f"[faidx] Failed to fetch sequence in {reg}\n")
            out_f.write(f">{reg}\n")
            if not continue_on_error:
                exit_code=1
            continue
        res=fetch_sequence(fasta_path,fai_index,seq_name,start,end)
        if res is None:
            sys.stderr.write(f"[faidx] Failed to fetch sequence in {reg}\n")
            if not continue_on_error:
                exit_code=1
            continue
        seq_str,status,s_val,e_val,full_len=res
        if status=="zero":
            sys.stderr.write(f"[faidx] Zero length sequence: {reg}\n")
            out_f.write(f">{reg}\n")
            continue
        if status=="truncated":
            sys.stderr.write(f"[faidx] Truncated sequence: {reg}\n")
        if revcomp_flag:
            seq_str=revcomp(seq_str)
        suffix=get_suffix(revcomp_flag,mark_strand)
        hdr=f"{reg}{suffix}" if suffix else reg
        out_f.write(f">{hdr}\n")
        if line_length<=0:
            out_f.write(seq_str+"\n")
        else:
            for i in range(0,len(seq_str),line_length):
                out_f.write(seq_str[i:i+line_length]+"\n")
    if output_file:
        out_f.close()
    return exit_code

def parse_sam_file(path):
    try:
        with open(path,'rb') as fb:
            magic=fb.read(4)
            if magic==b'BAM\x01':
                return parse_bam_file(path)
    except FileNotFoundError:
        return None,None,None
    header=[]
    refs={}
    records=[]
    open_func=open
    mode='r'
    if path.endswith('.gz'):
        open_func=gzip.open
        mode='rt'
    try:
        with open_func(path,mode) as f:
            for line in f:
                if line.startswith('@'):
                    header.append(line.rstrip('\n'))
                    if line.startswith('@SQ'):
                        parts=line.strip().split('\t')
                        sn=None
                        ln=None
                        for p in parts:
                            if p.startswith('SN:'):
                                sn=p[3:]
                            if p.startswith('LN:'):
                                try:
                                    ln=int(p[3:])
                                except:
                                    ln=None
                        if sn and ln is not None:
                            refs[sn]=ln
                else:
                    if not line.strip():
                        continue
                    fields=line.rstrip('\n').split('\t')
                    if len(fields)<11:
                        continue
                    try:
                        rec={
                            'qname':fields[0],
                            'flag':int(fields[1]),
                            'rname':fields[2],
                            'pos':int(fields[3]),
                            'mapq':int(fields[4]),
                            'cigar':fields[5],
                            'rnext':fields[6],
                            'pnext':int(fields[7]) if fields[7]!='0' else 0,
                            'tlen':int(fields[8]),
                            'seq':fields[9],
                            'qual':fields[10],
                            'tags':fields[11:],
                            'raw':line.rstrip('\n')
                        }
                    except:
                        continue
                    records.append(rec)
    except FileNotFoundError:
        return None,None,None
    return header,refs,records

def parse_bam_file(path):
    import struct
    try:
        with gzip.open(path,'rb') as gz:
            data=gz.read()
    except Exception:
        return None,None,None
    offset=0
    if len(data)<4 or data[0:4]!=b'BAM\x01':
        return None,None,None
    offset=4
    if offset+4>len(data):
        return None,None,None
    l_text=struct.unpack('<i',data[offset:offset+4])[0]
    offset+=4
    text=data[offset:offset+l_text].decode('utf-8',errors='ignore') if l_text>0 else ""
    offset+=l_text
    if offset+4>len(data):
        return None,None,None
    n_ref=struct.unpack('<i',data[offset:offset+4])[0]
    offset+=4
    refs={}
    ref_names=[]
    header=[]
    if text:
        for line in text.split('\n'):
            if line:
                header.append(line)
                if line.startswith('@SQ'):
                    parts=line.split('\t')
                    sn=None
                    ln=None
                    for p in parts:
                        if p.startswith('SN:'):
                            sn=p[3:]
                        if p.startswith('LN:'):
                            try:
                                ln=int(p[3:])
                            except:
                                ln=None
                    if sn and ln is not None:
                        refs[sn]=ln
    for i in range(n_ref):
        if offset+4>len(data):
            break
        l_name=struct.unpack('<i',data[offset:offset+4])[0]
        offset+=4
        if offset+l_name>len(data):
            break
        name_bytes=data[offset:offset+l_name]
        offset+=l_name
        name=name_bytes.split(b'\x00')[0].decode()
        ref_names.append(name)
        if offset+4>len(data):
            break
        l_ref=struct.unpack('<i',data[offset:offset+4])[0]
        offset+=4
        if name not in refs:
            refs[name]=l_ref
    records=[]
    while offset < len(data):
        if offset+4>len(data):
            break
        block_size=struct.unpack('<i',data[offset:offset+4])[0]
        offset+=4
        if offset+block_size>len(data):
            break
        block=data[offset:offset+block_size]
        offset+=block_size
        if len(block)<32:
            continue
        refID,pos,bin_mq_nl,flag_nc,l_seq,next_refID,next_pos,tlen=struct.unpack('<8i',block[0:32])
        bin_val=(bin_mq_nl>>16)&0xFFFF
        mq=(bin_mq_nl>>8)&0xFF
        l_read_name=bin_mq_nl&0xFF
        flag=flag_nc&0xFFFF
        n_cigar=(flag_nc>>16)&0xFFFF
        p=32
        if p+l_read_name>len(block):
            continue
        read_name_bytes=block[p:p+l_read_name]
        p+=l_read_name
        qname=read_name_bytes.split(b'\x00')[0].decode(errors='ignore')
        cigar_str=""
        if n_cigar>0:
            cigar_ops=[]
            for _ in range(n_cigar):
                if p+4>len(block):
                    break
                cigar=struct.unpack('<I',block[p:p+4])[0]
                p+=4
                op_len=cigar>>4
                op=cigar&0xF
                op_chars="MIDNSHP=X"
                if op < len(op_chars):
                    cigar_ops.append(f"{op_len}{op_chars[op]}")
                else:
                    cigar_ops.append(f"{op_len}M")
            cigar_str=''.join(cigar_ops) if cigar_ops else "*"
        else:
            cigar_str="*"
        seq_bytes_len=(l_seq+1)//2
        seq="*"
        if l_seq>0:
            if p+seq_bytes_len<=len(block):
                seq_bytes=block[p:p+seq_bytes_len]
                p+=seq_bytes_len
                bases="=ACMGRSVTWYHKDBN"
                seq_chars=[]
                for i in range(l_seq):
                    byte=seq_bytes[i//2]
                    if i%2==0:
                        b=(byte>>4)&0xF
                    else:
                        b=byte&0xF
                    seq_chars.append(bases[b] if b < len(bases) else 'N')
                seq=''.join(seq_chars)
        qual="*"
        if l_seq>0:
            if p+l_seq<=len(block):
                qual_bytes=block[p:p+l_seq]
                p+=l_seq
                if all(b==0xFF for b in qual_bytes):
                    qual="*"
                else:
                    qual=''.join(chr(b+33) for b in qual_bytes)
        rname=ref_names[refID] if 0 <= refID < len(ref_names) else "*"
        rnext=ref_names[next_refID] if 0 <= next_refID < len(ref_names) else ("=" if next_refID==refID else "*")
        rec={
            'qname':qname,
            'flag':flag,
            'rname':rname,
            'pos':pos+1,
            'mapq':mq,
            'cigar':cigar_str,
            'rnext':rnext,
            'pnext':next_pos+1,
            'tlen':tlen,
            'seq':seq,
            'qual':qual,
            'tags':[],
            'raw':f"{qname}\t{flag}\t{rname}\t{pos+1}\t{mq}\t{cigar_str}\t{rnext}\t{next_pos+1}\t{tlen}\t{seq}\t{qual}"
        }
        records.append(rec)
    return header,refs,records

def cigar_ref_len(cigar):
    import re
    total=0
    for length,op in re.findall(r'(\d+)([MIDNSHP=X])',cigar):
        l=int(length)
        if op in "MDN=X":
            total+=l
    return total

def cigar_query_len(cigar):
    import re
    total=0
    for length,op in re.findall(r'(\d+)([MIDNSHP=X])',cigar):
        l=int(length)
        if op in "MIS=X":
            total+=l
    return total

