        return 0
    with_header=False
    header_only=False
    count=False
    output_file=None
    input_file=None
    regions=[]
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg in ("-h","--with-header"):
            with_header=True
            i+=1
        elif arg in ("-H","--header-only"):
            header_only=True
            i+=1
        elif arg=="--no-header":
            i+=1
        elif arg in ("-c","--count"):
            count=True
            i+=1
        elif arg in ("-o","--output"):
            if i+1 < len(argv):
                output_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg.startswith("-o"):
            output_file=arg[2:] if len(arg)>2 else None
            i+=1
        elif arg=="-S":
            i+=1
        elif arg in ("-b","--bam","-C","--cram","-1","--fast","-u","--uncompressed"):
            i+=1
        elif arg in ("-@","-T","-t","-f","-F","-q","-G","-l","-m","-e","-r","-R","-L","-N","-d","-D","-s","-U","--unoutput","--output-unselected","--save-counts","--subsample","--subsample-seed","--add-flags","--remove-flags","-x","--remove-tag","--keep-tag","-B","-z","--input-fmt-option","-O","--output-fmt","--output-fmt-option","--reference","--threads","--write-index","--verbosity","--no-PG","-M","--use-index","--region-file","--regions-file","-X","--customized-index","-n","--exclude-no-read_group","-p","--unmap","-P","--fetch-pairs"):
            if "=" in arg:
                i+=1
            else:
                if i+1 < len(argv) and not argv[i+1].startswith("-"):
                    # some options take arg, but for simplicity skip next if not file?
                    # We'll skip next if option is known to take arg
                    takes_arg_list=["-@","-T","-t","-f","-F","-G","-q","-l","-m","-e","-r","-R","-L","-N","-d","-D","-s","-U","--save-counts","--subsample","--subsample-seed","--add-flags","--remove-flags","--remove-tag","--keep-tag","--sanitize","--input-fmt-option","--output-fmt","-O","--output-fmt-option","--reference","--threads","--write-index","--verbosity","--region-file","--regions-file","--fai-reference","--target-file","--targets-file","--qname-file","--read-group","--read-group-file","--library","--tag","--tag-file","--min-MQ","--min-qlen","--expr","--incl-flags","--include-flags","--require-flags","--exclude-flags","--unoutput","--output-unselected"]
                    if arg in takes_arg_list or any(arg.startswith(o+"=") is False and arg==o for o in takes_arg_list):
                        i+=2
                    else:
                        i+=1
                else:
                    i+=1
        elif arg.startswith("-"):
            i+=1
        else:
            if input_file is None:
                input_file=arg
            else:
                regions.append(arg)
            i+=1
    if input_file is None:
        sys.stderr.write("[main_samview] fail to read the header from \"-\".\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"[main_samview] fail to read the header from \"{input_file}\".\n")
        return 1
    header,refs,records=parse_sam_file(input_file)
    if header is None:
        sys.stderr.write(f"[main_samview] fail to read the header from \"{input_file}\".\n")
        return 1
    def parse_region_view(reg):
        reg=reg.strip()
        if ':' not in reg:
            return (reg,None,None)
        rname,coords=reg.split(':',1)
        coords=coords.replace(',','')
        if '-' in coords:
            s,e=coords.split('-',1)
            try:
                start=int(s) if s else None
            except:
                start=None
            try:
                end=int(e) if e else None
            except:
                end=None
            return (rname,start,end)
        else:
            try:
                pos=int(coords)
                return (rname,pos,pos)
            except:
                return (rname,None,None)
    filtered=records
    if regions:
        parsed=[parse_region_view(r) for r in regions]
        new=[]
        for rec in records:
            for rn,st,en in parsed:
                if rec['rname']!=rn:
                    continue
                if st is None and en is None:
                    new.append(rec)
                    break
                ref_len=cigar_ref_len(rec['cigar'])
                rec_end=rec['pos']+ref_len-1 if ref_len>0 else rec['pos']
                s=st if st is not None else 1
                e=en if en is not None else 10**12
                if rec['pos']<=e and rec_end>=s:
                    new.append(rec)
                    break
        filtered=new
    out_f=sys.stdout
    if output_file:
        out_f=open(output_file,'w')
    def make_pg():
        cl=' '.join(sys.argv)
        return f"@PG\tID:samtools\tPN:samtools\tVN:{VERSION}\tCL:{cl}"
    pg_line=make_pg()
    if count:
        out_f.write(f"{len(filtered)}\n")
        if output_file:
            out_f.close()
        return 0
    if header_only:
        for h in header:
            out_f.write(h+"\n")
        out_f.write(pg_line+"\n")
        if output_file:
            out_f.close()
        return 0
    if with_header:
        for h in header:
            out_f.write(h+"\n")
        out_f.write(pg_line+"\n")
        for rec in filtered:
            out_f.write(rec['raw']+"\n")
        if output_file:
            out_f.close()
        return 0
    else:
        for rec in filtered:
            out_f.write(rec['raw']+"\n")
        if output_file:
            out_f.close()
        return 0

def cmd_flagstat(argv):
    output_fmt="default"
    input_file=None
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg in ("-O","--output-fmt"):
            if i+1 < len(argv):
                fmt=argv[i+1]
                output_fmt=fmt.split(',')[0]
                i+=2
            else:
                i+=1
        elif arg.startswith("-O"):
            fmt=arg[2:]
            if fmt.startswith("="):
                fmt=fmt[1:]
            output_fmt=fmt.split(',')[0]
            i+=1
        elif arg.startswith("--output-fmt="):
            fmt=arg.split('=',1)[1]
            output_fmt=fmt.split(',')[0]
            i+=1
        elif arg in ("-@","--threads","--input-fmt-option","--verbosity"):
            if i+1 < len(argv):
                i+=2
            else:
                i+=1
        elif arg.startswith("--input-fmt-option=") or arg.startswith("--verbosity="):
            i+=1
        elif arg.startswith("-"):
            i+=1
        else:
            if input_file is None:
                input_file=arg
            i+=1
    if input_file is None:
        sys.stderr.write("Usage: samtools flagstat [options] <in.bam>\n")
        sys.stderr.write("      --input-fmt-option OPT[=VAL]\n               Specify a single input file format option in the form\n               of OPTION or OPTION=VALUE\n  -@, --threads INT\n               Number of additional threads to use [0]\n      --verbosity INT\n               Set level of verbosity\n\nSee https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\nfor more details.\n  -O, --output-fmt FORMAT[,OPT[=VAL]]...\n               Specify output format (json, tsv)\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"samtools flagstat: failed to open \"{input_file}\": No such file or directory\n")
        return 1
    header,refs,records=parse_sam_file(input_file)
    if header is None:
        sys.stderr.write(f"samtools flagstat: failed to open \"{input_file}\": No such file or directory\n")
        return 1
    def detailed_counts(recs):
        total=len(recs)
        primary=len([r for r in recs if not (r['flag']&0x100) and not (r['flag']&0x800)])
        secondary=len([r for r in recs if r['flag']&0x100])
        supplementary=len([r for r in recs if r['flag']&0x800])
        duplicates=len([r for r in recs if r['flag']&0x400])
        primary_dup=len([r for r in recs if (r['flag']&0x400) and not (r['flag']&0x100) and not (r['flag']&0x800)])
        mapped=len([r for r in recs if not (r['flag']&0x4)])
        primary_mapped=len([r for r in recs if not (r['flag']&0x4) and not (r['flag']&0x100) and not (r['flag']&0x800)])
        paired=len([r for r in recs if r['flag']&0x1])
        read1=len([r for r in recs if r['flag']&0x40])
        read2=len([r for r in recs if r['flag']&0x80])
        properly_paired=len([r for r in recs if r['flag']&0x2])
        with_self_and_mate_mapped=len([r for r in recs if (r['flag']&0x1) and not (r['flag']&0x4) and not (r['flag']&0x8)])
        singletons=len([r for r in recs if (r['flag']&0x1) and not (r['flag']&0x4) and (r['flag']&0x8)])
        mate_diff_chr=len([r for r in recs if (r['flag']&0x1) and not (r['flag']&0x4) and not (r['flag']&0x8) and r['rname']!=r['rnext'] and r['rnext']!="=" and r['rnext']!="*"])
        mate_diff_chr_q5=len([r for r in recs if (r['flag']&0x1) and not (r['flag']&0x4) and not (r['flag']&0x8) and r['rname']!=r['rnext'] and r['rnext']!="=" and r['rnext']!="*" and r['mapq']>=5])
        return {
            'total':total,'primary':primary,'secondary':secondary,'supplementary':supplementary,
            'duplicates':duplicates,'primary_duplicates':primary_dup,'mapped':mapped,'primary_mapped':primary_mapped,
            'paired':paired,'read1':read1,'read2':read2,'properly_paired':properly_paired,
            'with_self_and_mate_mapped':with_self_and_mate_mapped,'singletons':singletons,
            'mate_diff_chr':mate_diff_chr,'mate_diff_chr_q5':mate_diff_chr_q5
        }
    qc_passed=[r for r in records if not (r['flag']&0x200)]
    qc_failed=[r for r in records if r['flag']&0x200]
    qp=detailed_counts(qc_passed)
    qf=detailed_counts(qc_failed)
    if output_fmt=="json":
        def perc(num,denom):
            if denom==0:
                return None
            return round(num/denom*100,2)
        def fmt_perc(v):
            if v is None:
                return "null"
            return f"{v:.2f}"
        def format_json_counts(d):
            lines=[]
            lines.append(' "total": %d, ' % d['total'])
            lines.append(' "primary": %d, ' % d['primary'])
            lines.append(' "secondary": %d, ' % d['secondary'])
            lines.append(' "supplementary": %d, ' % d['supplementary'])
            lines.append(' "duplicates": %d, ' % d['duplicates'])
            lines.append(' "primary duplicates": %d, ' % d['primary_duplicates'])
            lines.append(' "mapped": %d, ' % d['mapped'])
            mapped_perc=perc(d['mapped'],d['total'])
            lines.append(' "mapped %%": %s, ' % (fmt_perc(mapped_perc) if mapped_perc is not None else "null"))
            lines.append(' "primary mapped": %d, ' % d['primary_mapped'])
            primary_mapped_perc=perc(d['primary_mapped'],d['primary'])
            lines.append(' "primary mapped %%": %s, ' % (fmt_perc(primary_mapped_perc) if primary_mapped_perc is not None else "null"))
            lines.append(' "paired in sequencing": %d, ' % d['paired'])
            lines.append(' "read1": %d, ' % d['read1'])
            lines.append(' "read2": %d, ' % d['read2'])
            lines.append(' "properly paired": %d, ' % d['properly_paired'])
            properly_perc=perc(d['properly_paired'],d['paired'])
            lines.append(' "properly paired %%": %s, ' % (fmt_perc(properly_perc) if properly_perc is not None else "null"))
            lines.append(' "with itself and mate mapped": %d, ' % d['with_self_and_mate_mapped'])
            lines.append(' "singletons": %d, ' % d['singletons'])
            singleton_perc=perc(d['singletons'],d['paired'])
            lines.append(' "singletons %%": %s, ' % (fmt_perc(singleton_perc) if singleton_perc is not None else "null"))
            lines.append(' "with mate mapped to a different chr": %d, ' % d['mate_diff_chr'])
            lines.append(' "with mate mapped to a different chr (mapQ >= 5)": %d ' % d['mate_diff_chr_q5'])
            return lines
        qp_lines=format_json_counts(qp)
        qf_lines=format_json_counts(qf)
        sys.stdout.write("{\n")
        sys.stdout.write(' "QC-passed reads": { \n')
        for line in qp_lines:
            sys.stdout.write(line+"\n")
        sys.stdout.write(" },\n")
        sys.stdout.write(' "QC-failed reads": { \n')
        for line in qf_lines:
            sys.stdout.write(line+"\n")
        sys.stdout.write(" }\n")
        sys.stdout.write("}\n")
        return 0
    elif output_fmt=="tsv":
        def fmt_counts(a,b):
            return f"{a}\t{b}"
        def fmt_perc_val(num,denom):
            if denom==0:
                return "N/A"
            return f"{num/denom*100:.2f}%"
        out=[]
        out.append(f"{fmt_counts(qp['total'],qf['total'])}\ttotal (QC-passed reads + QC-failed reads)")
        out.append(f"{fmt_counts(qp['primary'],qf['primary'])}\tprimary")
        out.append(f"{fmt_counts(qp['secondary'],qf['secondary'])}\tsecondary")
        out.append(f"{fmt_counts(qp['supplementary'],qf['supplementary'])}\tsupplementary")
        out.append(f"{fmt_counts(qp['duplicates'],qf['duplicates'])}\tduplicates")
        out.append(f"{fmt_counts(qp['primary_duplicates'],qf['primary_duplicates'])}\tprimary duplicates")
        out.append(f"{fmt_counts(qp['mapped'],qf['mapped'])}\tmapped")
        out.append(f"{fmt_perc_val(qp['mapped'],qp['total'])}\t{fmt_perc_val(qf['mapped'],qf['total'])}\tmapped %")
        out.append(f"{fmt_counts(qp['primary_mapped'],qf['primary_mapped'])}\tprimary mapped")
        out.append(f"{fmt_perc_val(qp['primary_mapped'],qp['primary'])}\t{fmt_perc_val(qf['primary_mapped'],qf['primary'])}\tprimary mapped %")
        out.append(f"{fmt_counts(qp['paired'],qf['paired'])}\tpaired in sequencing")
        out.append(f"{fmt_counts(qp['read1'],qf['read1'])}\tread1")
        out.append(f"{fmt_counts(qp['read2'],qf['read2'])}\tread2")
        out.append(f"{fmt_counts(qp['properly_paired'],qf['properly_paired'])}\tproperly paired")
        out.append(f"{fmt_perc_val(qp['properly_paired'],qp['paired'])}\t{fmt_perc_val(qf['properly_paired'],qf['paired'])}\tproperly paired %")
        out.append(f"{fmt_counts(qp['with_self_and_mate_mapped'],qf['with_self_and_mate_mapped'])}\twith itself and mate mapped")
        out.append(f"{fmt_counts(qp['singletons'],qf['singletons'])}\tsingletons")
        out.append(f"{fmt_perc_val(qp['singletons'],qp['paired'])}\t{fmt_perc_val(qf['singletons'],qf['paired'])}\tsingletons %")
        out.append(f"{fmt_counts(qp['mate_diff_chr'],qf['mate_diff_chr'])}\twith mate mapped to a different chr")
        out.append(f"{fmt_counts(qp['mate_diff_chr_q5'],qf['mate_diff_chr_q5'])}\twith mate mapped to a different chr (mapQ>=5)")
        for line in out:
            sys.stdout.write(line+"\n")
        return 0
    else:
        def line(a,b,desc):
            return f"{a} + {b} {desc}\n"
        def line_perc(a,b,desc,num_a,den_a,num_b,den_b):
            def perc(num,den):
                if den==0:
                    return "N/A"
                return f"{num/den*100:.2f}%"
            return f"{a} + {b} {desc} ({perc(num_a,den_a)} : {perc(num_b,den_b)})\n"
        sys.stdout.write(line(qp['total'],qf['total'],"in total (QC-passed reads + QC-failed reads)"))
        sys.stdout.write(line(qp['primary'],qf['primary'],"primary"))
        sys.stdout.write(line(qp['secondary'],qf['secondary'],"secondary"))
        sys.stdout.write(line(qp['supplementary'],qf['supplementary'],"supplementary"))
        sys.stdout.write(line(qp['duplicates'],qf['duplicates'],"duplicates"))
        sys.stdout.write(line(qp['primary_duplicates'],qf['primary_duplicates'],"primary duplicates"))
        sys.stdout.write(line_perc(qp['mapped'],qf['mapped'],"mapped",qp['mapped'],qp['total'],qf['mapped'],qf['total']))
        sys.stdout.write(line_perc(qp['primary_mapped'],qf['primary_mapped'],"primary mapped",qp['primary_mapped'],qp['primary'],qf['primary_mapped'],qf['primary']))
        sys.stdout.write(line(qp['paired'],qf['paired'],"paired in sequencing"))
        sys.stdout.write(line(qp['read1'],qf['read1'],"read1"))
        sys.stdout.write(line(qp['read2'],qf['read2'],"read2"))
        sys.stdout.write(line_perc(qp['properly_paired'],qf['properly_paired'],"properly paired",qp['properly_paired'],qp['paired'],qf['properly_paired'],qf['paired']))
        sys.stdout.write(line(qp['with_self_and_mate_mapped'],qf['with_self_and_mate_mapped'],"with itself and mate mapped"))
        sys.stdout.write(line_perc(qp['singletons'],qf['singletons'],"singletons",qp['singletons'],qp['paired'],qf['singletons'],qf['paired']))
        sys.stdout.write(line(qp['mate_diff_chr'],qf['mate_diff_chr'],"with mate mapped to a different chr"))
        sys.stdout.write(line(qp['mate_diff_chr_q5'],qf['mate_diff_chr_q5'],"with mate mapped to a different chr (mapQ>=5)"))
        return 0

def cmd_idxstats(argv):
    if not argv or all(a.startswith("-") for a in argv):
        sys.stdout.write("Usage: samtools idxstats [options] <in.bam>\n")
        sys.stdout.write("  -X           Include customized index file\n")
        sys.stdout.write("      --input-fmt-option OPT[=VAL]\n               Specify a single input file format option in the form\n               of OPTION or OPTION=VALUE\n")
        sys.stdout.write("  -@, --threads INT\n               Number of additional threads to use [0]\n")
        sys.stdout.write("      --verbosity INT\n               Set level of verbosity\n\nSee https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\nfor more details.\n")
        return 1
    input_file=None
    for arg in argv:
        if not arg.startswith("-"):
            input_file=arg
    if input_file is None:
        sys.stdout.write("Usage: samtools idxstats [options] <in.bam>\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"[E::idxstats] fail to open file {input_file}\n")
        return 1
    header,refs,records=parse_sam_file(input_file)
    if header is None:
        sys.stderr.write(f"[E::idxstats] fail to open file {input_file}\n")
        return 1
    mapped_counts=defaultdict(int)
    unmapped_counts=defaultdict(int)
    for rec in records:
        if rec['flag']&0x4:
            if rec['rname']=="*":
                unmapped_counts["*"]+=1
            else:
                unmapped_counts[rec['rname']]+=1
        else:
            mapped_counts[rec['rname']]+=1
    for rname,length in refs.items():
        mapped=mapped_counts.get(rname,0)
        unmapped=unmapped_counts.get(rname,0)
        sys.stdout.write(f"{rname}\t{length}\t{mapped}\t{unmapped}\n")
    star_mapped=mapped_counts.get("*",0)
    star_unmapped=unmapped_counts.get("*",0)
    sys.stdout.write(f"*\t0\t{star_mapped}\t{star_unmapped}\n")
    return 0

def cmd_depth(argv):
    if not argv:
        sys.stdout.write("Usage: samtools depth [options] in.bam [in.bam ...]\n\nOptions:\n  -a           Output all positions (including zero depth)\n  -a -a, -aa   Output absolutely all positions, including unused ref seqs\n  -r REG       Specify a region in chr or chr:from-to syntax\n  -b FILE      Use bed FILE for list of regions\n  -f FILE      Specify list of input BAM/SAM/CRAM filenames\n  -X           Use custom index files (in -X *.bam *.bam.bai order)\n  -g INT       Remove specified flags from default filter-out flag list\n  -G, --excl-flags FLAGS\n               Add specified flags to the  default filter-out flag list\n               [UNMAP,SECONDARY,QCFAIL,DUP]\n      --incl-flags FLAGS\n               Only include records with at least one the FLAGs present [0]\n      --require-flags FLAGS\n               Only include records with all of the FLAGs present [0]\n  -H           Print a file header line\n  -l INT       Minimum read length [0]\n  -o FILE      Write output to FILE [stdout]\n  -q, --min-BQ INT\n               Filter bases with base quality smaller than INT [0]\n  -Q, --min-MQ INT\n               Filter alignments with mapping quality smaller than INT [0]\n  -J           Include reads with deletions in depth computation\n  -s           Do not count overlapping reads within a template\n      --input-fmt-option OPT[=VAL]\n               Specify a single input file format option in the form\n               of OPTION or OPTION=VALUE\n      --reference FILE\n               Reference sequence FASTA FILE [null]\n  -@, --threads INT\n               Number of additional threads to use [0]\n      --verbosity INT\n               Set level of verbosity\n\nSee https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\nfor more details.\n")
        return 1
    show_all=False
    show_all_abs=False
    print_header=False
    output_file=None
    region=None
    bed_file=None
    input_files=[]
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg=="-a":
            if show_all:
                show_all_abs=True
            else:
                show_all=True
            i+=1
        elif arg=="-aa":
            show_all=True
            show_all_abs=True
            i+=1
        elif arg=="-H":
            print_header=True
            i+=1
        elif arg=="-o":
            if i+1 < len(argv):
                output_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg=="-r":
            if i+1 < len(argv):
                region=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg=="-b":
            if i+1 < len(argv):
                bed_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg=="-f":
            if i+1 < len(argv):
                list_file=argv[i+1]
                try:
                    with open(list_file) as lf:
                        for line in lf:
                            line=line.strip()
                            if line:
                                input_files.append(line)
                except:
                    pass
                i+=2
            else:
                i+=1
        elif arg.startswith("-"):
            if "=" in arg:
                i+=1
            else:
                if i+1 < len(argv) and not argv[i+1].startswith("-"):
                    if arg in ("-g","-G","-l","-q","-Q","-r","-b","-f","-o","-@","--threads","--input-fmt-option","--reference","--verbosity","--incl-flags","--require-flags","--excl-flags"):
                        i+=2
                    else:
                        i+=1
                else:
                    i+=1
        else:
            input_files.append(arg)
            i+=1
    if not input_files:
        sys.stdout.write("Usage: samtools depth [options] in.bam [in.bam ...]\n")
        return 1
    def compute_depth(path):
        hdr,refs,recs=parse_sam_file(path)
        if hdr is None:
            return None,None
        depth=defaultdict(lambda: defaultdict(int))
        for rec in recs:
            flag=rec['flag']
            if flag&0x4 or flag&0x100 or flag&0x200 or flag&0x400:
                continue
            rname=rec['rname']
            if rname=="*":
                continue
            pos=rec['pos']
            cigar=rec['cigar']
            import re
            ref_pos=pos
            for length_str,op in re.findall(r'(\d+)([MIDNSHP=X])',cigar):
                length=int(length_str)
                if op in "M=XDN":
                    for _ in range(length):
                        depth[rname][ref_pos]+=1
                        ref_pos+=1
                elif op in "IHS P":
                    pass
        return depth,refs
    total_depth=defaultdict(lambda: defaultdict(int))
    all_refs={}
    for fpath in input_files:
        d,refs=compute_depth(fpath)
        if d is None:
            sys.stderr.write(f"samtools depth: failed to open {fpath}\n")
            return 1
        for rname,pos_dict in d.items():
            for pos,cnt in pos_dict.items():
                total_depth[rname][pos]+=cnt
        for rname,length in refs.items():
            if rname not in all_refs or length>all_refs[rname]:
                all_refs[rname]=length
    filter_regions=[]
    if region:
        rname,st,en=parse_region(region)
        filter_regions.append((rname,st,en))
    if bed_file:
        try:
            with open(bed_file) as bf:
                for line in bf:
                    if not line.strip() or line.startswith('#'):
                        continue
                    parts=line.strip().split()
                    if len(parts)<3:
                        continue
                    rname=parts[0]
                    try:
                        start=int(parts[1])+1
                        end=int(parts[2])
                    except:
                        continue
                    filter_regions.append((rname,start,end))
        except FileNotFoundError:
            sys.stderr.write(f"samtools depth: failed to open BED file {bed_file}\n")
            return 1
    out_f=sys.stdout
    if output_file:
        out_f=open(output_file,'w')
    if print_header:
        hdr_line="#CHROM\tPOS"
        for fpath in input_files:
            hdr_line+=f"\t{fpath}"
        out_f.write(hdr_line+"\n")
    def in_filter(rname,pos):
        if not filter_regions:
            return True
        for fr_rname,fr_st,fr_en in filter_regions:
            if fr_rname!=rname:
                continue
            s=fr_st if fr_st is not None else 1
            e=fr_en if fr_en is not None else 10**12
            if s<=pos<=e:
                return True
        return False
    for rname,length in all_refs.items():
        depth_dict=total_depth.get(rname,{})
        if show_all or show_all_abs:
            for pos in range(1,length+1):
                if not in_filter(rname,pos):
                    continue
                cnt=depth_dict.get(pos,0)
                out_f.write(f"{rname}\t{pos}\t{cnt}\n")
        else:
            for pos in sorted(depth_dict.keys()):
                if not in_filter(rname,pos):
                    continue
                cnt=depth_dict[pos]
                if cnt>0:
                    out_f.write(f"{rname}\t{pos}\t{cnt}\n")
    if output_file:
        out_f.close()
    return 0

def cmd_coverage(argv):
    if not argv or all(a.startswith("-") for a in argv):
        sys.stdout.write("Usage: samtools coverage [options] in1.bam [in2.bam [...]]\n\nInput options:\n  -b, --bam-list FILE     list of input BAM filenames, one per line\n  -l, --min-read-len INT  ignore reads shorter than INT bp [0]\n  -q, --min-MQ INT        mapping quality threshold [0]\n  -Q, --min-BQ INT        base quality threshold [0]\n  --rf <int|str>          required flags: skip reads with mask bits unset []\n  --ff <int|str>          filter flags: skip reads with mask bits set \n                                      [UNMAP,SECONDARY,QCFAIL,DUP]\n  -d, --depth INT         maximum allowed coverage depth [1000000].\n                          If 0, depth is set to the maximum integer value,\n                          effectively removing any depth limit.\n      --min-depth INT     minimum coverage depth below which a position \n                          to be ignored [1]\nOutput options:\n  -m, --histogram         show histogram instead of tabular output\n  -D, --plot-depth        plot depth instead of tabular output\n  -A, --ascii             show only ASCII characters in histogram\n  -o, --output FILE       write output to FILE [stdout]\n  -H, --no-header         don't print a header in tabular mode\n  -w, --n-bins INT        number of bins in histogram [terminal width - 40]\n  -r, --region REG        show specified region. Format: chr:start-end. \n  -h, --help              help (this page)\n\nGeneric options:\n      --input-fmt-option OPT[=VAL]\n               Specify a single input file format option in the form\n               of OPTION or OPTION=VALUE\n      --reference FILE\n               Reference sequence FASTA FILE [null]\n      --verbosity INT\n               Set level of verbosity\n\nSee https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\nfor more details.\n\nSee manpage for additional details.\n  rname       Reference name / chromosome\n  startpos    Start position\n  endpos      End position (or sequence length)\n  numreads    Number reads aligned to the region (after filtering)\n  covbases    Number of covered bases with depth >= 1\n  coverage    Percentage of covered bases [0..100]\n  meandepth   Mean depth of coverage\n  meanbaseq   Mean baseQ in covered region\n  meanmapq    Mean mapQ of selected reads\n")
        return 1
    no_header=False
    histogram=False
    ascii_only=False
    output_file=None
    min_read_len=0
    min_mapq=0
    region=None
    bam_list_file=None
    input_files=[]
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg in ("-H","--no-header"):
            no_header=True
            i+=1
        elif arg in ("-m","--histogram"):
            histogram=True
            i+=1
        elif arg in ("-A","--ascii"):
            ascii_only=True
            i+=1
        elif arg in ("-o","--output"):
            if i+1 < len(argv):
                output_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg in ("-b","--bam-list"):
            if i+1 < len(argv):
                bam_list_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg in ("-l","--min-read-len"):
            if i+1 < len(argv):
                try:
                    min_read_len=int(argv[i+1])
                except:
                    min_read_len=0
                i+=2
            else:
                i+=1
