        sys.stderr.write(f"Failed to read header for \"{input_file}\"\n")
        return 1
    hdr,refs,recs=parse_sam_file(input_file)
    if hdr is None:
        sys.stderr.write(f"Failed to read header for \"{input_file}\"\n")
        return 1
    sys.stderr.write("[M::bam2fq_mainloop] discarded 0 singletons\n")
    sys.stderr.write(f"[M::bam2fq_mainloop] processed {len(recs)} reads\n")
    for rec in recs:
        qname=rec['qname']
        flag=rec['flag']
        seq=rec['seq']
        qual=rec['qual']
        if flag&0x40:
            qname_out=f"{qname}/1"
        elif flag&0x80:
            qname_out=f"{qname}/2"
        else:
            qname_out=qname
        if qual=="*":
            qual_out="B"*len(seq) if seq!="*" else "*"
        else:
            qual_out=qual
        sys.stdout.write(f"@{qname_out}\n{seq}\n+\n{qual_out}\n")
    return 0

