        return 0
    with_header=False
    header_only=False
    count=False
    output_file=None
    input_file=None
    regions=[]
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg in ("-h","--with-header"):
            with_header=True
            i+=1
        elif arg in ("-H","--header-only"):
            header_only=True
            i+=1
        elif arg=="--no-header":
            i+=1
        elif arg in ("-c","--count"):
            count=True
            i+=1
        elif arg in ("-o","--output"):
            if i+1 < len(argv):
                output_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg.startswith("-o"):
            output_file=arg[2:] if len(arg)>2 else None
            i+=1
        elif arg=="-S":
            i+=1
        elif arg in ("-b","--bam","-C","--cram","-1","--fast","-u","--uncompressed"):
            i+=1
        elif arg in ("-@","-T","-t","-f","-F","-q","-G","-l","-m","-e","-r","-R","-L","-N","-d","-D","-s","-U","--unoutput","--output-unselected","--save-counts","--subsample","--subsample-seed","--add-flags","--remove-flags","-x","--remove-tag","--keep-tag","-B","-z","--input-fmt-option","-O","--output-fmt","--output-fmt-option","--reference","--threads","--write-index","--verbosity","--no-PG","-M","--use-index","--region-file","--regions-file","-X","--customized-index","-n","--exclude-no-read_group","-p","--unmap","-P","--fetch-pairs"):
            if "=" in arg:
                i+=1
            else:
                if i+1 < len(argv) and not argv[i+1].startswith("-"):
                    # some options take arg, but for simplicity skip next if not file?
                    # We'll skip next if option is known to take arg
                    takes_arg_list=["-@","-T","-t","-f","-F","-G","-q","-l","-m","-e","-r","-R","-L","-N","-d","-D","-s","-U","--save-counts","--subsample","--subsample-seed","--add-flags","--remove-flags","--remove-tag","--keep-tag","--sanitize","--input-fmt-option","--output-fmt","-O","--output-fmt-option","--reference","--threads","--write-index","--verbosity","--region-file","--regions-file","--fai-reference","--target-file","--targets-file","--qname-file","--read-group","--read-group-file","--library","--tag","--tag-file","--min-MQ","--min-qlen","--expr","--incl-flags","--include-flags","--require-flags","--exclude-flags","--unoutput","--output-unselected"]
                    if arg in takes_arg_list or any(arg.startswith(o+"=") is False and arg==o for o in takes_arg_list):
                        i+=2
                    else:
                        i+=1
                else:
                    i+=1
        elif arg.startswith("-"):
            i+=1
        else:
            if input_file is None:
                input_file=arg
            else:
                regions.append(arg)
            i+=1
    if input_file is None:
        sys.stderr.write("[main_samview] fail to read the header from \"-\".\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"[main_samview] fail to read the header from \"{input_file}\".\n")
        return 1
    header,refs,records=parse_sam_file(input_file)
    if header is None:
        sys.stderr.write(f"[main_samview] fail to read the header from \"{input_file}\".\n")
        return 1
    def parse_region_view(reg):
        reg=reg.strip()
        if ':' not in reg:
            return (reg,None,None)
        rname,coords=reg.split(':',1)
        coords=coords.replace(',','')
        if '-' in coords:
            s,e=coords.split('-',1)
            try:
                start=int(s) if s else None
            except:
                start=None
            try:
                end=int(e) if e else None
            except:
                end=None
            return (rname,start,end)
        else:
            try:
                pos=int(coords)
                return (rname,pos,pos)
            except:
                return (rname,None,None)
    filtered=records
    if regions:
        parsed=[parse_region_view(r) for r in regions]
        new=[]
        for rec in records:
            for rn,st,en in parsed:
                if rec['rname']!=rn:
                    continue
                if st is None and en is None:
                    new.append(rec)
                    break
                ref_len=cigar_ref_len(rec['cigar'])
                rec_end=rec['pos']+ref_len-1 if ref_len>0 else rec['pos']
                s=st if st is not None else 1
                e=en if en is not None else 10**12
                if rec['pos']<=e and rec_end>=s:
                    new.append(rec)
                    break
        filtered=new
    out_f=sys.stdout
    if output_file:
