def cmd_quickcheck(argv):
    verbose=False
    quiet=False
    unmapped=False
    files=[]
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg=="-v":
            verbose=True
            i+=1
        elif arg=="-q":
            quiet=True
            i+=1
        elif arg=="-u":
            unmapped=True
            i+=1
        elif arg in ("-vq","-qv"):
            verbose=True
            quiet=True
            i+=1
        elif arg.startswith("-"):
            i+=1
        else:
            files.append(arg)
            i+=1
    if not files:
        sys.stdout.write("Usage: samtools quickcheck [options] <input> [...]\nOptions:\n  -v              verbose output (repeat for more verbosity)\n  -q              suppress warning messages\n  -u              unmapped input (do not require targets in header)\n\nNotes:\n\n1. By default quickcheck will emit a warning message if and only if a file\n   fails the checks, in which case the exit status is non-zero.  Under normal\n   behaviour with valid data it will be silent and has a zero exit status.\n   The warning messages are purely for manual inspection and should not be \n   parsed by scripts.\n\n2. In order to use this command programmatically, you should check its exit\n   status.  One way to use quickcheck might be as a check that all BAM files in\n   a directory are okay:\n\n\tsamtools quickcheck *.bam && echo 'all ok' \\\n\t   || echo 'fail!'\n\n   The first level of verbosity lists only files that fail to stdout.\n   To obtain a parsable list of files that have failed, use this option:\n\n\tsamtools quickcheck -qv *.bam > bad_bams.fofn \\\n\t   && echo 'all ok' \\\n\t   || echo 'some files failed check, see bad_bams.fofn'\n")
        return 1
    exit_code=0
    for fpath in files:
        if not os.path.exists(fpath):
            if not quiet:
                sys.stderr.write(f"{fpath} could not be opened for reading.\n")
            else:
                if verbose:
                    sys.stdout.write(f"{fpath}\n")
            exit_code=1
            continue
        hdr,refs,recs=parse_sam_file(fpath)
        if hdr is None:
            if not quiet:
                sys.stderr.write(f"{fpath} is not a valid SAM/BAM file\n")
            if verbose:
                sys.stdout.write(f"{fpath}\n")
            exit_code=1
            continue
        if not unmapped:
            if not refs:
                if not quiet:
                    sys.stderr.write(f"{fpath} has no targets in header\n")
                if verbose:
                    sys.stdout.write(f"{fpath}\n")
                exit_code=1
                continue
    return exit_code

def cmd_sort(argv):
    if not argv:
        sys.stderr.write("[W::hts_set_opt] Cannot change block size for this format\n")
        sys.stderr.write("samtools sort: failed to read header from \"-\"\n")
        return 1
    output_file=None
    input_file=None
    sort_by_name=False
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg=="-o":
            if i+1 < len(argv):
                output_file=argv[i+1]
                i+=2
            else:
                i+=1
        elif arg.startswith("-o"):
            output_file=arg[2:]
            i+=1
        elif arg=="-n" or arg=="-N":
            sort_by_name=True
            i+=1
        elif arg=="-t":
            if i+1 < len(argv):
                i+=2
            else:
                i+=1
        elif arg in ("-l","-u","-m","-M","-R","-K","-I","-w","-H","-T","--no-PG","--template-coordinate","-@","--threads","--input-fmt-option","-O","--output-fmt","--output-fmt-option","--reference","--write-index","--verbosity"):
            if "=" in arg:
                i+=1
            else:
                if i+1 < len(argv) and arg in ("-l","-m","-K","-I","-w","-T","-t","-O","--output-fmt","--output-fmt-option","--reference","-@","--threads","--input-fmt-option","--verbosity"):
                    i+=2
                else:
                    i+=1
        elif arg.startswith("-"):
            i+=1
        else:
            if input_file is None:
                input_file=arg
            i+=1
    if input_file is None:
        sys.stderr.write("[W::hts_set_opt] Cannot change block size for this format\n")
        sys.stderr.write("samtools sort: failed to read header from \"-\"\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"samtools sort: failed to open \"{input_file}\": No such file or directory\n")
        return 1
    hdr,refs,recs=parse_sam_file(input_file)
    if hdr is None:
        sys.stderr.write("samtools sort: failed to read header from \"-\"\n")
        return 1
    if sort_by_name:
        recs_sorted=sorted(recs,key=lambda r: r['qname'])
    else:
        ref_order={r:i for i,r in enumerate(refs.keys())}
        def sort_key(r):
            order=ref_order.get(r['rname'],9999)
            return (order,r['pos'],r['qname'])
        recs_sorted=sorted(recs,key=sort_key)
    out_f=sys.stdout
