    sys.stderr.write(f"[M::bam2fq_mainloop] processed {len(recs)} reads\n")
    for rec in recs:
        qname=rec['qname']
        flag=rec['flag']
        seq=rec['seq']
        qual=rec['qual']
        if flag&0x40:
